(()=>{
'use strict';
// Relative radii are schematic, ordered by common cation radius; not quantitative crystal data.
const metals={Li:{name:'Lithium',charge:1,radius:21},Na:{name:'Sodium',charge:1,radius:27},K:{name:'Potassium',charge:1,radius:33},Mg:{name:'Magnesium',charge:2,radius:20},Al:{name:'Aluminium',charge:3,radius:15}};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),smooth=t=>t*t*(3-2*t);
const density=m=>m.charge/m.radius**3;
function slidePositions(pressure){const t=clamp(pressure,0,100)/100,dx=260*smooth(Math.min(t*2,1)),dy=130*smooth(Math.max(t*2-1,0));return Array.from({length:16},(_,i)=>({x:195+(i%4)*65+(i<8?dx:0),y:115+Math.floor(i/4)*65+(i<8?dy:0)}));}
const foreignOrder=[5,10,2,13];
function packedAtoms(alloy=false){const atoms=Array.from({length:16},(_,i)=>({x:100+(i%4)*50+(Math.floor(i/4)%2)*25,y:100+Math.floor(i/4)*Math.sqrt(1875),r:alloy&&foreignOrder.includes(i)?33:25,foreign:alloy&&foreignOrder.includes(i)}));
if(alloy){for(let pass=0;pass<260;pass++)for(let i=0;i<atoms.length;i++)for(let j=i+1;j<atoms.length;j++){const a=atoms[i],b=atoms[j],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy),overlap=a.r+b.r-d;if(overlap>0){const move=(overlap+.001)/2;a.x-=dx/d*move;a.y-=dy/d*move;b.x+=dx/d*move;b.y+=dy/d*move;}}}
return atoms;}
function pureSlide(pressure){const shift=clamp(pressure,0,100)*.5,offset=((25+shift)%50),nearest=Math.min(offset,50-offset),lift=Math.sqrt(2500-nearest*nearest)-Math.sqrt(1875);return packedAtoms().map((a,i)=>({...a,x:a.x+(i<8?shift:0),y:a.y-(i<8?lift:0)}));}
if(typeof module!=='undefined'&&module.exports)module.exports={metals,density,slidePositions,packedAtoms,pureSlide};if(typeof document==='undefined')return;
const $=id=>document.getElementById(id),chargeText=n=>(n===1?'':n===2?'²':'³')+'⁺';
const electrons=(count,bounds)=>Array.from({length:count},(_,i)=>{const x=bounds.x+((i*.61803398875+.17)%1)*bounds.w,y=bounds.y+((i*.41421356+.31)%1)*bounds.h;return `<circle cx="${x}" cy="${y}" r="3.5" class="metal-electron"/>`;}).join('');
function initProperties(){if(!$('mb-game'))return;let mode='density',pressure=0,left='Na',right='Mg';
function structure(symbol){const m=metals[symbol];let s=`<title>${m.name}: nine ${m.charge}+ ion cores and ${9*m.charge} delocalised electrons</title><rect x="20" y="25" width="350" height="290" rx="25" class="metal-sea"/>`;for(let row=0;row<3;row++)for(let col=0;col<3;col++){const x=95+col*100,y=75+row*95;s+=`<circle cx="${x}" cy="${y}" r="${m.radius}" class="metal-core"/><text x="${x}" y="${y}" class="metal-core-label">${symbol}${chargeText(m.charge)}</text>`;}return s+electrons(9*m.charge,{x:30,y:35,w:330,h:270});}
function render(){for(const k of ['density','sliding'])$('mb-mode-'+k).setAttribute('aria-pressed',String(mode===k));$('mb-density').hidden=mode!=='density';$('mb-sliding').hidden=mode!=='sliding';
const a=metals[left],b=metals[right],da=density(a),db=density(b);for(const [side,symbol,other] of [['left',left,right],['right',right,left]]){const m=metals[symbol],o=metals[other];$('mb-'+side+'-diagram').innerHTML=structure(symbol);$('mb-'+side+'-charge').textContent='Cation charge: '+m.charge+'+';$('mb-'+side+'-radius').textContent='Relative cation radius: '+(m.radius===o.radius?'same':m.radius<o.radius?'smaller':'larger');$('mb-'+side+'-electrons').textContent=m.charge+' delocalised electron'+(m.charge===1?'':'s')+' per atom';$('mb-'+side+'-density').textContent='Charge density: '+(density(m)===density(o)?'same':density(m)>density(o)?'higher':'lower');}
const stronger=da>db?a:b;$('mb-prediction').textContent=da===db?'The same metal is selected, so this model predicts no difference.':stronger.name+' has the higher cation charge density in this comparison. Stronger attraction to the delocalised electrons generally favours greater hardness and a higher melting point. This is a trend-based prediction, not a complete ranking: crystal structure and electronic structure also affect real properties.';
const points=slidePositions(pressure),minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),maxY=Math.max(...points.map(p=>p.y));let svg='<title>Sixteen metal ions deform from four rows of four to two rows of eight</title>'+`<rect x="${minX-48}" y="${minY-50}" width="${maxX-minX+96}" height="${maxY-minY+100}" rx="25" class="metal-sea"/>`;
points.forEach((p,i)=>{svg+=`<circle cx="${p.x}" cy="${p.y}" r="20" class="metal-core ${i<8?'metal-moving':''}"/><text x="${p.x}" y="${p.y}" class="metal-core-label">+</text>`;});svg+=electrons(16,{x:minX-30,y:minY-30,w:maxX-minX+60,h:maxY-minY+60});const p=points[0];svg+=`<path d="M${p.x-65} ${p.y-65} L${p.x-23} ${p.y-23} M${p.x-23} ${p.y-23} l-16 -3 M${p.x-23} ${p.y-23} l-3 -16" class="metal-pressure-arrow"/><text x="${p.x-80}" y="${p.y-79}" class="metal-pressure-text">Pressure</text>`;
$('mb-sliding-diagram').innerHTML=svg;$('mb-pressure').value=pressure;$('mb-pressure-output').textContent=Math.round(pressure)+'%';$('mb-arrangement').textContent=pressure===0?'4 × 4':pressure===100?'2 × 8':'Layers sliding';$('mb-slide-state').textContent=pressure===100?'Two rows of eight ions. Metallic attraction is maintained.':'The upper two layers slide to the right, then down. Delocalised electrons remain shared.';
}
for(const modeName of ['density','sliding'])$('mb-mode-'+modeName).addEventListener('click',()=>{mode=modeName;render();});for(const side of ['left','right']){$('mb-'+side).innerHTML=Object.entries(metals).map(([symbol,m])=>`<option value="${symbol}">${m.name} · ${symbol}</option>`).join('');$('mb-'+side).value=side==='left'?left:right;$('mb-'+side).addEventListener('change',e=>{if(side==='left')left=e.target.value;else right=e.target.value;render();});}
$('mb-pressure').addEventListener('input',e=>{pressure=clamp(Number(e.target.value),0,100);render();});$('mb-reset').addEventListener('click',()=>{pressure=0;render();});render();
}
function initAlloys(){if(!$('alloy-game'))return;let pressure=0;const fixedAlloy=packedAtoms(true);
function lattice(alloy){const atoms=alloy?fixedAlloy:pureSlide(pressure);let svg=`<title>${alloy?'Alloy: distorted layers resist sliding':'Pure metal: close-packed layers slide under pressure'}</title><rect x="20" y="25" width="350" height="290" rx="25" class="metal-sea"/>`;
if(pressure>0){const length=15+pressure*.22;svg+=`<path d="M25 125 H${25+length} m-9 -5 l9 5 -9 5" class="alloy-force"/>`;}
atoms.forEach(a=>{svg+=`<circle cx="${a.x}" cy="${a.y}" r="${a.r}" class="${a.foreign?'alloy-foreign':'metal-core'}"/>`;});return svg;}
function render(){$('alloy-pure').innerHTML=lattice(false);$('alloy-mixture').innerHTML=lattice(true);$('alloy-pressure-output').textContent=pressure+'%';$('alloy-status').textContent=pressure===0?'Closely packed, regular layers in the pure metal; distorted layers in the alloy.':'The pure-metal layers slide. Different-sized atoms keep the alloy layers from sliding at the pressure shown.';$('alloy-resistance').textContent='The alloy remains fixed over this illustrative pressure range; sufficient stress can still deform real alloys.';}
$('alloy-pressure').addEventListener('input',e=>{pressure=clamp(Number(e.target.value),0,100);render();});$('alloy-reset').addEventListener('click',()=>{pressure=0;$('alloy-pressure').value=0;render();});render();}
initProperties();initAlloys();
})();
